<?php
namespace App\Http\Controllers\Api\V1\Guest;
use App\Http\Controllers\Controller; use App\Models\{Guest,PropertyWebSetting,User}; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash; use Illuminate\Validation\ValidationException;
class GuestAuthController extends Controller { public function register(Request $r){$d=$r->validate(['property_slug'=>'required|string','first_name'=>'required|string|max:120','last_name'=>'nullable|string|max:120','email'=>'required|email','phone'=>'nullable|string|max:50','password'=>'required|string|min:8|confirmed']);$web=PropertyWebSetting::where('slug',$d['property_slug'])->firstOrFail();if(User::where('email',$d['email'])->exists())throw ValidationException::withMessages(['email'=>'An account already exists for this email.']);$guest=Guest::firstOrCreate(['property_id'=>$web->property_id,'email'=>$d['email']],['first_name'=>$d['first_name'],'last_name'=>$d['last_name']??null,'phone'=>$d['phone']??null]);$user=User::create(['property_id'=>$web->property_id,'guest_id'=>$guest->id,'name'=>$guest->full_name,'email'=>$d['email'],'phone'=>$d['phone']??null,'password'=>$d['password'],'role'=>'guest','is_active'=>true]);return response()->json(['token'=>$user->createToken('guest-mobile')->plainTextToken,'user'=>$user,'guest'=>$guest],201);} public function login(Request $r){$d=$r->validate(['email'=>'required|email','password'=>'required|string','device_name'=>'nullable|string|max:120']);$u=User::where('email',$d['email'])->where('role','guest')->where('is_active',1)->first();if(!$u||!Hash::check($d['password'],$u->password))throw ValidationException::withMessages(['email'=>'The provided credentials are incorrect.']);return ['token'=>$u->createToken($d['device_name']??'guest-mobile')->plainTextToken,'user'=>$u,'guest'=>$u->guest];} public function logout(Request $r){$r->user()->currentAccessToken()?->delete();return ['message'=>'Signed out'];} }
